const e = $input.first().json;
const miss = ['envelope_version','business_id','lead_id','trace_id'].filter(k => !e[k]);
if (miss.length) throw new Error('LEAD:' + (e.lead_id || '') + '|TRACE:' + (e.trace_id || '') + '|invalid envelope, missing: ' + miss.join(', '));
return [{ json: e }];

const raw = $input.first().json;
let r = raw;
if (r && Array.isArray(r.candidates)) r = { content: (r.candidates[0] || {}).content };
if (r && r.content && Array.isArray(r.content.parts)) r = r.content.parts.map(p => p.text || '').join('');
else if (r.content !== undefined) r = r.content;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/^```json?\s*|```\s*$/g, '')); } catch (e) { r = null; } }
const c = $('Fetch Draft Context').first().json;
let subject = r && typeof r.subject === 'string' && r.subject.trim() ? r.subject.trim() : null;
let body = r && typeof r.body === 'string' && r.body.trim() ? r.body.trim() : null;
if (!subject || !body) {
  // deterministic fallback template: grounded facts only, never blocks on the LLM
  subject = 'Our recommendations for you - ' + c.business_name;
  const items = (c.items || []).map(i => '- ' + i.name + ' (' + i.currency + ' ' + i.price + '): ' + i.rationale).join('\n');
  body = 'Hi ' + (c.contact_name ? c.contact_name.split(' ')[0] : 'there') + ',\n\nThank you for your enquiry. Based on what you told us, we recommend:\n\n' + items + '\n\nReply to this email or visit a showroom and we will take care of the rest.\n\n' + c.business_name;
}
return [{ json: { lead_id: c.lead_id, business_id: c.business_id, trace_id: c.trace_id, subject, body } }];

const j = $input.first().json;
const approved = !!(j.data && j.data.approved === true);
const p = $('Persist Draft (PENDING_APPROVAL)').first().json;
const c = $('Fetch Draft Context').first().json;
return [{ json: { approved, draft_id: p.draft_id, trace_id: c.trace_id, reviewer: c.reviewer_email, customer_email: c.customer_email, redirect: c.customer_email_redirect, sender: c.sender_identity, business_name: c.business_name } }];

const j = $input.first().json;
let out;
if (Array.isArray(j.candidates)) {
  out = { ...j, __model: 'gemini-2.5-flash', __fallback: false };
} else if (Array.isArray(j.choices)) {
  const u = j.usage || {};
  out = { candidates: [{ content: { parts: [{ text: (j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '' }] },
    finishReason: (j.choices[0] && j.choices[0].finish_reason) || null }],
    usageMetadata: { promptTokenCount: u.prompt_tokens || 0, candidatesTokenCount: u.completion_tokens || 0, thoughtsTokenCount: 0 },
    __model: 'gpt-4o-mini', __fallback: true };
} else {
  out = { candidates: [], usageMetadata: {}, __model: 'unknown', __fallback: true };
}
return [{ json: out }];
